import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, deferred} from './wsTestSupport.js';
import {validateMessage} from './ws/validation.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {captureErrors} from '../shared/logCaptureTestSupport.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';

// What a client can reach over the socket, end to end: the frames are the contract, and no double of
// the server can stand in for one. The engine under test is the real `createServer`, driven by a real
// `ws` client, the same path a consumer's browser takes.

interface SummaryOnWire {
  sessionId: string;
  createdAt: unknown;
  updatedAt: unknown;
  entryCount: number;
}

interface Frame {
  type: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  index?: number;
  code?: string;
  message?: string;
  entry?: {content?: string};
  conversations?: SummaryOnWire[];
}

// `history` is the option re-cinq/HALEngine#144 adds to `createServer`, beside `resume`. It reaches the
// server through a spread of a plain object rather than through an options literal: until the option
// exists a literal is a type error, and these tests would fail on a compile error instead of on the
// missing behaviour.
interface EngineOptions {
  history?: {enabled: boolean};
  resume?: {enabled: boolean};
  orchestrator?: ChatOrchestrator;
}

const servers: HalServer[] = [];
const clients: WebSocket[] = [];

const errors = captureErrors();

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

const startEngine = async (sessionStore: SessionStore, options: EngineOptions = {}) => {
  const wired = {
    history: options.history,
    resume: options.resume,
    orchestrator: options.orchestrator ?? answeringOrchestrator,
  };
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    sessionStore,
    ...wired,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {base: `ws://127.0.0.1:${port}/hal/ws`};
};

const open = (url: string): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  return client;
};

// Opens a client, sends each frame once the connected frame arrives, and pings the moment any of the
// named answer frames shows up. The pong can only follow every frame the engine wrote before it, so
// what the promise resolves with is the whole answer, stray frames included.
const exchange = async (url: string, frames: unknown[], answers: string[]): Promise<Frame[]> => {
  const client = open(url);
  const seen: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      seen.push(frame);
      if (frame.type === 'connected') for (const sent of frames) client.send(JSON.stringify(sent));
      if (answers.includes(frame.type)) client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      if (frame.type === 'pong') resolve();
    });
  });
  return seen;
};

// The answer to a history request, whichever side of the feature flag the engine answers from.
const ANSWER = ['conversation_list', 'error'];

// A connect with nothing to ask: the pong follows the connected frame and everything the replay wrote.
const settle = (url: string): Promise<Frame[]> => exchange(url, [], ['connected']);

// Each conversation holds that many user entries, all sent at its own moment, so the store's activity
// order is the seed's and no clock the test cannot control decides an assertion.
const storeWith = (conversations: Array<[sessionId: string, userId: string, sentAt: string, entries?: number]>) => {
  const store = new InMemorySessionStore();
  for (const [sessionId, userId, sentAt, count = 1] of conversations) {
    const session = store.create(sessionId, userId);
    for (let nth = 0; nth < count; nth++) {
      session.entries.push({role: 'user', content: `${sessionId} ${nth}`, timestamp: sentAt});
    }
  }
  return store;
};

// A store with only the five original members, so the optional ones can be present, absent or lying.
const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

const answerFrame = (frames: Frame[]): Frame | undefined => frames.find(frame => frame.type === 'error');

// The times on the wire are either an ISO string or whatever a broken handler sent; the assertion reads
// the shape alone, since the value itself is the store's, asserted where the test knows it.
const isoShape = (value: unknown): unknown =>
  typeof value === 'string' && /^\d{4}-\d{2}-\d{2}T[\d.]+Z$/.test(value) ? 'ISO' : value;

const rowsOf = (frames: Frame[]): SummaryOnWire[] =>
  (frames.find(frame => frame.type === 'conversation_list')?.conversations ?? []).map(row => ({
    ...row,
    createdAt: isoShape(row.createdAt),
    updatedAt: isoShape(row.updatedAt),
  }));

// A turn that streams its first chunk and then holds, so a frame sent mid-turn lands inside the turn.
const heldAnswer = (until: Promise<void>): ChatOrchestrator => ({
  processMessage: async () => '',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'part'};
