describe('delivering a user conversation list over the websocket', () => {
  it('answers list_conversations with exactly one conversation_list carrying the conversations of the connecting user, newest first, times as ISO strings, and no stream_end', async () => {
    const at = (hour: number): string => `2026-09-30T0${hour}:00:00.000Z`;
    const store = storeWith([
      ['oldest', 'u1', at(1)],
      ['middle', 'u1', at(2), 3],
      ['newest', 'u1', at(3)],
    ]);
    const {base} = await startEngine(store, {history: {enabled: true}, resume: {enabled: true}});

    // Rejoined, not fresh: the store holds exactly the three conversations, the one in use among them.
    const frames = await exchange(`${base}?sessionId=middle`, [{type: 'list_conversations'}], ANSWER);
    const listed = frames.find(frame => frame.type === 'conversation_list');
    // The replay of the rejoined conversation is the resume's, not the list's; the protocol frames are
    // what this frame is answered with.
    const told = frames.filter(frame => !frame.type.startsWith('entry_')).map(frame => frame.type);

    expect({told, resumed: frames[0].resumed, listed}).toEqual({
      told: ['connected', 'conversation_list', 'pong'],
      resumed: true,
      listed: {
        type: 'conversation_list',
        conversations: [
          {sessionId: 'newest', createdAt: 'ISO', updatedAt: at(3), entryCount: 1},
          {sessionId: 'middle', createdAt: 'ISO', updatedAt: at(2), entryCount: 3},
          {sessionId: 'oldest', createdAt: 'ISO', updatedAt: at(1), entryCount: 1},
        ],
      },
    });
  });

  it('asks the store for the user on the socket with the paging fields the frame sent, never for a userId the frame names', async () => {
    const inner = storeWith([
      ['older', 'u1', '2026-09-30T08:00:00.000Z'],
      ['newer', 'u1', '2026-09-30T09:00:00.000Z'],
      ['theirs', 'u2', '2026-10-01T10:00:00.000Z'],
    ]);
    const asked: Array<{userId: unknown; options: unknown}> = [];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        asked.push({userId, options});
        return inner.listFor(userId, options);
      },
    };
    const {base} = await startEngine(store, {history: {enabled: true}});

    // The cursor is what a client holds from its previous page: both halves, as ISO strings. The
    // `userId` on the frame is a forgery; u2 has the newest conversation of all three.
    const before = {updatedAt: '2026-09-30T09:00:00.000Z', sessionId: 'newer'};
    const frames = await exchange(base, [{type: 'list_conversations', limit: 1, before, userId: 'u2'}], ANSWER);

    expect({asked, rows: rowsOf(frames).map(row => row.sessionId)}).toEqual({
      asked: [{userId: 'u1', options: {limit: 1, before}}],
      rows: ['older'],
    });
  });

  it('accepts the frame whatever history is set to, refusing a bad limit or a partial cursor with a message naming the field', () => {
    const cursor = {updatedAt: '2026-09-30T08:00:00.000Z', sessionId: 's1'};
    const cases: Array<[name: string, frame: unknown, field?: string]> = [
      ['bare', {type: 'list_conversations'}],
      ['limit one', {type: 'list_conversations', limit: 1}],
      ['limit two hundred', {type: 'list_conversations', limit: 200}],
      ['limit with cursor', {type: 'list_conversations', limit: 10, before: cursor}],
      ['limit zero', {type: 'list_conversations', limit: 0}, 'limit'],
      ['limit over two hundred', {type: 'list_conversations', limit: 201}, 'limit'],
      ['fractional limit', {type: 'list_conversations', limit: 1.5}, 'limit'],
      ['limit as a string', {type: 'list_conversations', limit: '10'}, 'limit'],
      ['before not a date', {type: 'list_conversations', before: 'not a date'}, 'before'],
      ['cursor without updatedAt', {type: 'list_conversations', before: {sessionId: 's1'}}, 'before'],
      ['cursor without sessionId', {type: 'list_conversations', before: {updatedAt: cursor.updatedAt}}, 'before'],
      ['cursor with an unusable time', {type: 'list_conversations', before: {...cursor, updatedAt: 'nope'}}, 'before'],
    ];

    const accepted: string[] = [];
    const refused: Array<{name: string; answer: string}> = [];
    for (const [name, frame, field] of cases) {
      const result = validateMessage(frame);
      const wanted = field === undefined ? result.valid : !result.valid && result.error.includes(field);
      if (wanted) accepted.push(name);
      else refused.push({name, answer: result.valid ? 'accepted' : result.error});
    }

    expect({accepted, refused}).toEqual({
      accepted: ['bare', 'limit one', 'limit two hundred', 'limit with cursor'],
      refused: [],
    });
  });

  it('answers history that cannot be honoured with one UNSUPPORTED error and no list, with the feature off or a store without listFor', async () => {
    const off = await startEngine(storeWith([['kept', 'u1', '2026-09-30T08:00:00.000Z']]));
    const unlistable = await startEngine(delegatingTo(storeWith([['kept', 'u1', '2026-09-30T08:00:00.000Z']])), {
      history: {enabled: true},
    });

    const withoutFeature = await exchange(off.base, [{type: 'list_conversations'}], ANSWER);
    const withoutList = await exchange(unlistable.base, [{type: 'list_conversations'}], ANSWER);

    const shape = (frames: Frame[]) => ({
      types: frames.map(frame => frame.type),
      code: answerFrame(frames)?.code,
      listed: frames.some(frame => frame.type === 'conversation_list'),
    });

    expect({featureOff: shape(withoutFeature), storeCannot: shape(withoutList)}).toEqual({
      featureOff: {types: ['connected', 'error', 'pong'], code: 'UNSUPPORTED', listed: false},
      storeCannot: {types: ['connected', 'error', 'pong'], code: 'UNSUPPORTED', listed: false},
    });
  });

  it('answers list_conversations sent during a streaming turn before that turn ends in stream_end', async () => {
    const gate = deferred();
    const {base} = await startEngine(new InMemorySessionStore(), {
      history: {enabled: true},
      orchestrator: heldAnswer(gate.until),
    });

    // An error frees the hold too: without the feature the turn still completes, and the assertion
    // below reads the missing list rather than the run hanging on a gate nothing released.
    const seen: Frame[] = [];
    let asked = false;
    const client = open(base);
    await new Promise<void>(resolve => {
      client.on('message', raw => {
        const frame = JSON.parse(String(raw)) as Frame;
        seen.push(frame);
        if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
        if (frame.type === 'entry_upsert' && !asked) {
          // Asked once, at the first entry: a repeat would answer twice and read as a broken handler.
          asked = true;
          client.send(JSON.stringify({type: 'list_conversations'}));
        }
        if (frame.type === 'conversation_list' || frame.type === 'error') gate.release();
        if (frame.type === 'stream_end') client.send(JSON.stringify({type: 'ping', timestamp: 2}));
        if (frame.type === 'pong') resolve();
      });
    });

    const order = seen.map(frame => frame.type);
    expect({
      asked: order.includes('conversation_list'),
      once: order.filter(type => type === 'conversation_list').length,
      answered: order.indexOf('conversation_list') < order.indexOf('stream_end'),
    }).toEqual({
      asked: true,
      once: 1,
      answered: true,
    });
  });

  it('answers a listFor that rejects with one SERVER_ERROR naming no store detail, keeps the socket open, and logs the failure with the session id', async () => {
    // A database detail, not a message for a client: the kind of string that names a host and a query.
    const DETAIL = 'ECONNRESET reading history for u1 at 10.1.2.3:27017';
    const store: SessionStore = {
      ...delegatingTo(new InMemorySessionStore()),
      listFor: async () => {
        throw new Error(DETAIL);
      },
    };
    const {base} = await startEngine(store, {history: {enabled: true}});

    // The ping after the error frame is answered only by a socket still open, which is the barrier.
    const frames = await exchange(base, [{type: 'list_conversations'}], ANSWER);
    const logged = errors.find(line => line.sessionId === frames[0].sessionId);

    expect({
      types: frames.map(frame => frame.type),
      code: answerFrame(frames)?.code,
      detailOnWire: JSON.stringify(frames).includes(DETAIL),
      logged: logged !== undefined,
      detailInLog: JSON.stringify(errors).includes(DETAIL),
    }).toEqual({
      types: ['connected', 'error', 'pong'],
      code: 'SERVER_ERROR',
      detailOnWire: false,
      logged: true,
      detailInLog: false,
    });
  });

  it('lists the conversation the connection is in among the rows, and answers a reconnect naming a row id with resumed and the replay', async () => {
    const store = storeWith([['earlier', 'u1', '2026-09-30T08:00:00.000Z', 2]]);
    const {base} = await startEngine(store, {history: {enabled: true}, resume: {enabled: true}});

    // A fresh connect, a look at the list, a row opened: the whole journey a history sidebar makes.
    const client = open(base);
    let ownId = '';
    const listed: Frame[] = [];
    await new Promise<void>(resolve => {
      client.on('message', raw => {
        const frame = JSON.parse(String(raw)) as Frame;
        listed.push(frame);
        if (frame.type === 'connected') {
          ownId = frame.sessionId ?? '';
          client.send(JSON.stringify({type: 'list_conversations'}));
        }
        if (frame.type === 'conversation_list' || frame.type === 'error') resolve();
      });
    });
    const rows = listed.find(frame => frame.type === 'conversation_list')?.conversations ?? [];
    client.close();
    await once(client, 'close');

    const again = await settle(`${base}?sessionId=earlier`);
    const replay = again
      .filter(frame => frame.type === 'entry_upsert')
      .map(frame => ({index: frame.index, content: frame.entry?.content}));

    expect({
      listed: rows.map(row => row.sessionId),
      ownEntries: rows.find(row => row.sessionId === ownId)?.entryCount,
      picked: rows.some(row => row.sessionId === 'earlier'),
      resumed: again[0]?.resumed,
      entryCount: again[0]?.entryCount,
      replay,
    }).toEqual({
      listed: [ownId, 'earlier'],
      ownEntries: 0,
      picked: true,
      resumed: true,
      entryCount: 2,
      replay: [
        {index: 0, content: 'earlier 0'},
        {index: 1, content: 'earlier 1'},
      ],
    });
  });
});

